1016		\lean{MIPStarRE.QPBT.exists_pasting_error}
1017		\leanok
1018		\uses{def:consistency, def:bracket, def:povm-conventions}
1019		Let $\mathcal D$ be a distribution on $(x, y_1, y_2) \in \mathcal X \times \mathcal Y_1 \times \mathcal Y_2$. For $i \in \{1,2\}$ let $\mathcal G_i$ be a collection of functions $g_i \colon \mathcal Y_i \to \mathcal R_i$ and let $\{(G_i)^x_g\}_{g \in \mathcal G_i}$ be families of measurements such that $\{(G_2)^x_g\}_g$ is projective for every $x$. Suppose further that for every pair $(x, y_1)$ of positive probability under the marginal of $\mathcal D$ on $\mathcal X \times \mathcal Y_1$ (the only pairs for which the conditional distribution of $y_2$ under $\mathcal D$ is defined; pairs of marginal probability zero are subject to no requirement) it holds that for $g_2 \ne g_2' \in \mathcal G_2$ the probability, on average over $y_2$ chosen from $\mathcal D$ conditioned on $(x, y_1)$, that $g_2(y_2) = g_2'(y_2)$ is at most $\eta$. Let $\{A^{x,y_1,y_2}_{a_1,\,a_2}\}$ be a family of projective measurements with outcomes $(a_1, a_2) \in \mathcal R_1 \times \mathcal R_2$ such that for $i \in \{1,2\}$,
1020		\begin{equation}\label{eq:pasting-1}
1021			A^{x,y_1,y_2}_{a_i} \ot \Id \simeq_\delta \Id \ot (G_i)^x_{[\operatorname{eval}_{y_i}(\cdot)=a_i]}
1022		\end{equation}
1023		and
1024		\begin{equation}\label{eq:pasting-2}
1025			A^{x,y_1,y_2}_{a_1,\,a_2} \ot \Id \simeq_\delta \Id \ot A^{x,y_1,y_2}_{a_1,\,a_2}\,,
1026		\end{equation}
1027		where $A^{x,y_1,y_2}_{a_i}$ denotes the marginal on the $i$-th part of the outcome (Definition~\ref{def:povm-conventions}). Define a family of measurements $\{J^x_{g_1,\,g_2}\}$ by
1028		\begin{equation}\label{eq:pasting-2a}
1029			J^x_{g_1,\,g_2} = (G_2)^x_{g_2}\, (G_1)^x_{g_1}\, (G_2)^x_{g_2}\,.
1030		\end{equation}
1031		Then there is a
1032		\begin{equation}\label{eq:def-deltap}
1033			\delta_{\mathrm{pasting}} = \delta_{\mathrm{pasting}}(\eta, \delta) = \poly(\eta, \delta)
1034		\end{equation}
1035		such that
1036		\begin{equation}\label{eq:pasting-3}
1037			A^{x,y_1,y_2}_{a_1,\,a_2} \ot \Id \simeq_{\delta_{\mathrm{pasting}}} \Id \ot J^x_{[\operatorname{eval}_{y_1}(\cdot)=a_1,\, \operatorname{eval}_{y_2}(\cdot)=a_2]}\,.
1038		\end{equation}
1039		Neither the exponent nor the constant in $\poly(\eta, \delta)$ is made explicit in the source; both are universal constants inherited from the proof of Fact 4.35 in \cite{Natarajan2018NEEXP}. The literal product-form convention for this notation is incompatible with the unrestricted error domain in the lemma; a two-dimensional counterexample and the required correction are recorded in \cite{gap:qpbt_pasting-product-error}.
1040	\end{lemma}
1041	\begin{proof}
1042		\leanok
1043		\uses{lem:pasting-one-sided-explicit-error, lem:pasting-coarse-commutator,
1044			lem:pasting-measurement, lem:pasting-scalar-error, lem:pasting-defect-bound}
1045		Use the fixed Schmidt mirror of the second codeword family on Alice's
1046		register. Its coarse consistency defect is at most $2\delta$ and its fine
1047		defect at most $2\delta+\eta$. The distinct-family commutator comparison
1048		then proves the conclusion without a register-exchange assumption.
1049		For the universal coarse-commutator constant $C\geq1$, one may take
1050		$\delta_{\mathrm{pasting}}=(3C+19)(\eta^{1/4}+\delta^{1/8})$.
1051		On the unit square use Lemma~\ref{lem:pasting-scalar-error}; outside it,
1052		this error is at least $1$, so Lemma~\ref{lem:pasting-defect-bound} applies.
1053		Thus the polynomial notation here uses the additive correction documented
1054		in \cite{gap:qpbt_pasting-product-error}, not the refuted product contract.
1055	\end{proof}
